// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateProject Create a project (standalone deployments)
	// (POST /api/v1/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// GetProject Get a project
	// (GET /api/v1/projects/{project_id})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// GetSnapshot Get snapshot metadata
	// (GET /api/v1/snapshots/{snapshot_id})
	GetSnapshot(ctx context.Context, request GetSnapshotRequestObject) (GetSnapshotResponseObject, error)
	// GetSnapshotDiff Compare a snapshot with a base snapshot
	// (GET /api/v1/snapshots/{snapshot_id}/diff)
	GetSnapshotDiff(ctx context.Context, request GetSnapshotDiffRequestObject) (GetSnapshotDiffResponseObject, error)
	// GetSnapshotFile Download a file of a snapshot
	// (GET /api/v1/snapshots/{snapshot_id}/file)
	GetSnapshotFile(ctx context.Context, request GetSnapshotFileRequestObject) (GetSnapshotFileResponseObject, error)
	// RestoreSnapshot Restore a snapshot (or one path of it) onto a branch
	// (POST /api/v1/snapshots/{snapshot_id}/restore)
	RestoreSnapshot(ctx context.Context, request RestoreSnapshotRequestObject) (RestoreSnapshotResponseObject, error)
	// ListSnapshotTree List one directory of a snapshot
	// (GET /api/v1/snapshots/{snapshot_id}/tree)
	ListSnapshotTree(ctx context.Context, request ListSnapshotTreeRequestObject) (ListSnapshotTreeResponseObject, error)
	// CreateWorkspace Create a project-level workspace and its main branch
	// (POST /api/v1/workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
	// GetWorkspace Get a workspace
	// (GET /api/v1/workspaces/{workspace_id})
	GetWorkspace(ctx context.Context, request GetWorkspaceRequestObject) (GetWorkspaceResponseObject, error)
	// ListBranches List the branches of a workspace
	// (GET /api/v1/workspaces/{workspace_id}/branches)
	ListBranches(ctx context.Context, request ListBranchesRequestObject) (ListBranchesResponseObject, error)
	// CreateCommit Commit changes to a branch (the only way to create a snapshot)
	// (POST /api/v1/workspaces/{workspace_id}/commits)
	CreateCommit(ctx context.Context, request CreateCommitRequestObject) (CreateCommitResponseObject, error)
	// PutObject Upload a whole file into the workspace staging area
	// (PUT /api/v1/workspaces/{workspace_id}/objects)
	PutObject(ctx context.Context, request PutObjectRequestObject) (PutObjectResponseObject, error)
	// GetTimeline List snapshots, newest first
	// (GET /api/v1/workspaces/{workspace_id}/timeline)
	GetTimeline(ctx context.Context, request GetTimelineRequestObject) (GetTimelineResponseObject, error)
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness probe
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

